  "steps": [
    {
      "name": "HV Enable / Testing",
      "entry": "Pallet in ST30 (ZS-3001 / X33), guard door closed (ZS-3002 / X32), E-stop healthy (ES-0001 / X0), and no result latched (neither PASS M310 nor FAIL M311)",
      "exit": "Tester reports PASS (HP-3003 / X30), tester reports FAIL (HP-3004 / X31), guard door opens (NOT X32), or E-stop chain lost (NOT X0)"
    },
    {
      "name": "Result Latched / Done",
      "entry": "Tester reports PASS (HP-3003 / X30 sets M310) or FAIL (HP-3004 / X31 sets M311)",
      "exit": "Pallet leaves ST30 (falling edge of ZS-3001 / X33 resets M310 and M311)"
    }
  ],
  "interlocks": [
    {
      "cause": "Guard door opened (ZS-3002 / X32 open) or E-stop chain broken (ES-0001 / X0 open)",
      "effect": "Immediately de-energises HiPot start / HV enable (HP-3005 / Y30) and turns off HV-on beacon (HL-3006 / Y31)"
    },
    {
      "cause": "PASS (M310) or FAIL (M311) result latched",
      "effect": "De-energises HiPot start / HV enable (HP-3005 / Y30) and HV-on beacon (HL-3006 / Y31)"
    },
    {
      "cause": "Pallet not present (ZS-3001 / X33 open)",
      "effect": "Inhibits HiPot start / HV enable (HP-3005 / Y30) and HV-on beacon (HL-3006 / Y31)"
    }
  ],
